-- Migration: Question generation — REG batch 24 (30 questions)
-- Date: 2026-03-01
-- Topic: Tax-Exempt Organizations
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Controlled entity payment rules (royalties exceeding FMV)
(3, 'Tax-Exempt Organizations', 'Redstone University, a 501(c)(3) institution, owns 100% of BookCo, a for-profit subsidiary. BookCo pays the university $150,000 in annual royalties for use of the university''s name and logo when comparable royalties would be $120,000. Under the controlled entity rules, how is this royalty income treated for UBIT purposes?', '["Fully excluded from UBIT as passive royalty income", "Only the $120,000 fair market value portion is included in UBIT", "The $30,000 excess over fair market value is included in UBIT", "The entire $150,000 is included in UBIT because BookCo is a controlled entity"]'::jsonb, 2, 'Under IRC Section 512(b)(13), royalties received from a controlled entity (80%+ ownership) are treated as unrelated business income to the extent they exceed fair market value. Only the $30,000 excess ($150,000 minus $120,000 FMV) is included in UBIT. The general passive income exclusion for royalties does not apply to the portion exceeding FMV from a controlled subsidiary. Including the entire $150,000 would be incorrect because the FMV portion retains its passive income exclusion.', 'medium', 3),

-- Q2: easy / L1 — Form 990-N e-Postcard filing threshold
(3, 'Tax-Exempt Organizations', 'What is the filing threshold for Form 990-N (e-Postcard)?', '["Gross receipts of $100,000 or less", "Gross receipts normally $50,000 or less", "Total assets under $250,000", "All organizations with fewer than 10 employees"]'::jsonb, 1, 'Under IRC Section 6033, tax-exempt organizations with gross receipts normally $50,000 or less may file the electronic Form 990-N (e-Postcard) instead of Form 990 or 990-EZ. The e-Postcard requires only basic information: name, address, EIN, and confirmation of continued eligibility. The $100,000 threshold is incorrect and does not correspond to any Form 990 filing tier.', 'easy', 1),

-- Q3: medium / L3 — Section 501(h) expenditure test election application
(3, 'Tax-Exempt Organizations', 'Caring Hands Foundation, a 501(c)(3) public charity with $800,000 in exempt purpose expenditures, elects the Section 501(h) expenditure test. The organization spends $100,000 on direct lobbying and $25,000 on grassroots lobbying during the tax year. What is the consequence under the Section 501(h) limits?', '["The organization loses its tax-exempt status because total lobbying exceeds the statutory ceiling", "The organization must pay a 25% excise tax on the excess lobbying expenditures", "The organization must repay all lobbying expenditures to retain exempt status", "Both lobbying amounts are within the permitted limits for this expenditure level"]'::jsonb, 3, 'Under IRC Section 501(h), a public charity with $800,000 in exempt purpose expenditures may spend up to $145,000 on total lobbying (20% of the first $500,000 plus 15% of the next $300,000). The grassroots limit is 25% of the lobbying nontaxable amount ($36,250). Total lobbying of $125,000 and grassroots of $25,000 both fall within these ceilings. Loss of exempt status requires exceeding 150% of the limit over a four-year averaging period, not a single-year overage.', 'medium', 3),

-- Q4: easy / L2 — Dissolution clause requirement in organizational test
(3, 'Tax-Exempt Organizations', 'A nonprofit applying for 501(c)(3) status includes bylaws limiting its activities to educational purposes. However, the articles of incorporation contain no provision addressing what happens to assets if the organization ceases to exist. What is the most likely outcome of the IRS review?', '["The application will be denied because the articles lack a required dissolution clause", "The application will be approved because the bylaws sufficiently limit the organization''s purposes", "The application will be approved if the organization pledges to add a dissolution clause within one year", "The application will be denied because bylaws cannot substitute for articles of incorporation"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the organizational test requires that governing documents include a dissolution clause providing that assets will be distributed to another exempt organization or to the government upon dissolution. Without this clause, the IRS will deny the application regardless of how well operational activities align with exempt purposes. The issue is specifically the missing dissolution clause, not the validity of the bylaws as a limiting document.', 'easy', 2),

-- Q5: medium / L2 — Personal property rents vs. real property rents (10% incidental rule)
(3, 'Tax-Exempt Organizations', 'Hilltop Community Foundation, a 501(c)(3), leases a furnished office suite to a commercial tenant. Annual rent is $100,000, of which $18,000 is attributable to office furniture and equipment (personal property) and $82,000 to the building space (real property). How is the rental income treated for UBIT purposes?', '["The entire $100,000 is excluded from UBIT as passive rental income", "Only the $82,000 real property rent is subject to UBIT", "The $18,000 personal property rent is included in UBIT because it exceeds the 10% incidental threshold", "The entire $100,000 is subject to UBIT because any personal property component taints the entire lease"]'::jsonb, 2, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT, but rents from personal property are included unless the personal property component is incidental (less than 10% of total rents). The $18,000 personal property portion is 18% of total rents, exceeding the 10% threshold, so it is included in UBIT. The $82,000 real property rent remains excluded. The entire lease is not tainted; only the personal property portion loses the exclusion when it exceeds 10%.', 'medium', 2),

-- Q6: medium / L2 — Section 4940 excise tax rate computation (1.39%)
(3, 'Tax-Exempt Organizations', 'Westfield Family Foundation, a private foundation, has net investment income of $3,200,000 for 2026, consisting of $1,800,000 in capital gains and $1,400,000 in dividends and interest. Under Section 4940, what is the excise tax on this net investment income?', '["$32,000", "$44,480", "$64,000", "$160,000"]'::jsonb, 1, 'Under IRC Section 4940, private foundations are subject to a 1.39% excise tax on net investment income, which includes capital gains, dividends, interest, and other investment income less allocable expenses. The tax is $3,200,000 multiplied by 1.39%, equaling $44,480. The $32,000 figure incorrectly applies a 1% rate, while $64,000 and $160,000 reflect incorrect rates of 2% and 5%, respectively.', 'medium', 2),

-- Q7: hard / L4 — Private inurement vs. private benefit doctrine distinction
(3, 'Tax-Exempt Organizations', 'Brightway Education Foundation, a 501(c)(3), contracts with a for-profit consulting firm owned by an unrelated third party who is not an officer, director, or person with substantial influence over the organization. The consulting fee of $400,000 significantly exceeds the $150,000 fair market value. The board did not solicit competing bids. Analyze whether this arrangement implicates the private inurement prohibition, the private benefit doctrine, or both.', '["Only the private inurement prohibition applies because the payment exceeds fair market value", "Both private inurement and private benefit apply because any excessive payment triggers both doctrines", "Neither doctrine applies because the foundation has discretion to select consultants without competitive bidding", "Only the private benefit doctrine applies because the consultant is not an insider or disqualified person"]'::jsonb, 3, 'Under IRC Section 501(c)(3), private inurement applies only to transactions benefiting insiders with a personal and private interest in the organization (officers, directors, key employees). Because the consultant is an unrelated third party, inurement does not apply. However, the private benefit doctrine is broader and prohibits conferring more than incidental benefits on any person, insider or not. Paying $400,000 for $150,000-value services provides substantial private benefit, potentially jeopardizing exempt status.', 'hard', 4),

-- Q8: hard / L4 — Section 4945 expenditure responsibility for grants to non-charities
(3, 'Tax-Exempt Organizations', 'Heritage Arts Foundation, a private foundation, makes a $200,000 grant to a 501(c)(4) civic league to fund community art programs. The foundation does not require written reports on use of funds, does not maintain the right to inspect records, and does not obtain pre-grant assurance of charitable use. Evaluate this grant under Section 4945.', '["The grant is a taxable expenditure because the foundation failed to exercise expenditure responsibility over a grant to a non-501(c)(3) organization", "The grant is permissible because 501(c)(4) organizations pursue community welfare aligned with charitable purposes", "The grant is a taxable expenditure only if the civic league uses the funds for lobbying", "The grant is permissible because private foundations may grant to any tax-exempt organization without restrictions"]'::jsonb, 0, 'Under IRC Section 4945(d)(4), grants by private foundations to organizations other than public charities are taxable expenditures unless the foundation exercises expenditure responsibility per Section 4945(h). This requires pre-grant assurance, periodic reports, and record-keeping demonstrating proper use of funds. Heritage failed all three requirements. The 20% initial excise tax applies to the $200,000. The grant''s charitable purpose does not excuse lack of expenditure responsibility when the grantee is not a 501(c)(3).', 'hard', 4),

-- Q9: easy / L1 — Research exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Which type of research income is excluded from UBIT under Section 512?', '["Research performed exclusively for private for-profit companies", "Proprietary research kept confidential by the organization", "Research performed for the United States government or a college or university", "Clinical trial research funded by pharmaceutical companies"]'::jsonb, 2, 'Under IRC Section 512(b)(9), income from research performed for the United States government or for a college, university, or hospital is excluded from UBIT. Research results made freely available to the public also qualify for exclusion. Proprietary research performed under contract for private companies does not qualify because the results are not publicly available and the activity primarily serves private interests.', 'easy', 1),

-- Q10: easy / L1 — Form 990 filing deadline
(3, 'Tax-Exempt Organizations', 'What is the due date for filing Form 990 for a calendar-year tax-exempt organization?', '["March 15", "April 15", "June 15", "May 15"]'::jsonb, 3, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the end of the organization''s tax year. For calendar-year organizations (year ending December 31), the due date is May 15. March 15 is the due date for S corporation and partnership returns. April 15 is the individual income tax deadline. Extensions of up to six months are available using Form 8868.', 'easy', 1),

-- Q11: easy / L1 — Churches as automatic public charities
(3, 'Tax-Exempt Organizations', 'Under Section 509(a), which type of organization is automatically classified as a public charity regardless of its funding sources?', '["A church", "A donor-advised fund", "A private operating foundation", "A social welfare organization"]'::jsonb, 0, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(i), churches are automatically classified as public charities regardless of whether they receive broad public support. Schools, hospitals, and certain medical research organizations also receive automatic public charity status. Donor-advised funds are component funds of a sponsoring charity, not independently classified. Private operating foundations and social welfare organizations under 501(c)(4) are not public charities.', 'easy', 1),

-- Q12: easy / L1 — Convenience exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Under Section 513(a)(2), what does the convenience exclusion exempt from UBIT?', '["Activities performed during normal business hours", "Activities conducted primarily for the convenience of members, students, patients, or employees", "Sales of merchandise at below-market prices", "Activities operated by part-time staff"]'::jsonb, 1, 'Under IRC Section 513(a)(2), a trade or business carried on for the convenience of the organization''s members, students, patients, officers, or employees is excluded from UBIT. A classic example is a hospital cafeteria serving staff and patients. The exclusion is based on whom the activity primarily serves, not the pricing model, operating hours, or staffing structure.', 'easy', 1),

-- Q13: medium / L3 — NOL deduction for UBIT computation
(3, 'Tax-Exempt Organizations', 'Northern Heritage Trust, a 501(c)(3), has unrelated business income of $45,000 and deductible expenses of $60,000 in 2025. In 2026, the trust earns $80,000 of unrelated business income with $50,000 in connected expenses. After applying the $1,000 specific deduction, how does the 2025 net operating loss affect 2026 UBTI?', '["The $15,000 NOL carries forward and reduces 2026 UBTI to $14,000", "The NOL cannot offset UBIT because tax-exempt organizations are not permitted NOL deductions", "The $15,000 NOL carries forward and reduces 2026 UBTI to $13,000", "The NOL can only offset up to 50% of 2026 UBTI, reducing it to $14,500"]'::jsonb, 0, 'Under IRC Section 512(b)(6), a net operating loss deduction is allowed for UBIT, computed using only unrelated business income items. Per Section 512(b)(12), the $1,000 specific deduction is not used in computing the NOL. The 2025 NOL is $15,000 ($45,000 minus $60,000). The 2026 UBTI is $80,000 minus $50,000 expenses, minus $15,000 NOL carryforward, minus $1,000 specific deduction, equaling $14,000. The $13,000 answer incorrectly includes the specific deduction in the NOL computation.', 'medium', 3),

-- Q14: medium / L2 — Supporting organization under Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Lakewood Educational Services operates exclusively to provide administrative support and fundraising for Lakewood Public Library, a 501(c)(3) public charity. The organization receives 85% of its funding from the library''s endowment rather than public contributions. Under Section 509(a)(3), how is this organization classified?', '["A private foundation because it does not meet the one-third public support test", "A private operating foundation because it actively conducts educational programs", "A public charity only if it receives at least one-third of its support from the general public", "A public charity classified as a supporting organization"]'::jsonb, 3, 'Under IRC Section 509(a)(3), an organization is classified as a public charity if it is organized and operated exclusively to support one or more public charities. Because Lakewood Educational Services supports Lakewood Public Library (a public charity), it qualifies as a supporting organization regardless of its funding sources. The one-third support test under Section 509(a)(1) is an alternative path to public charity status, not a requirement for supporting organizations.', 'medium', 2),

-- Q15: medium / L3 — Form 990-PF requirement for all private foundations regardless of size
(3, 'Tax-Exempt Organizations', 'Alpine Heritage Foundation, a small private foundation, has gross receipts of $35,000 and total assets of $180,000 for the current year. The treasurer believes it qualifies to file Form 990-EZ due to its small size. Which form must this foundation actually file?', '["Form 990-EZ because gross receipts are under $200,000 and assets are under $500,000", "Form 990-N because gross receipts are under $50,000", "Form 990-PF because all private foundations must file this form regardless of size", "Form 990 because private foundations cannot file simplified returns"]'::jsonb, 2, 'Under IRC Section 6033, all private foundations must file Form 990-PF regardless of their gross receipts or total assets. This is a stricter requirement than for public charities, which may file Form 990-EZ or 990-N based on size thresholds. The treasurer''s assumption that 990-EZ is available is incorrect because private foundations are categorically excluded from simplified filing options. Form 990-PF includes detailed excise tax computations unique to foundations.', 'medium', 3),

-- Q16: easy / L1 — Bingo games exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Under Section 513(f), when is income from bingo games excluded from UBIT?', '["When the bingo games are conducted less than four times per year", "When bingo is legal and not ordinarily carried out on a commercial basis in the jurisdiction", "When bingo proceeds are used exclusively for charitable purposes", "When the bingo games are operated by paid staff rather than volunteers"]'::jsonb, 1, 'Under IRC Section 513(f), income from bingo games is excluded from UBIT if the game is legal under state and local law and is not ordinarily carried out on a commercial basis in the jurisdiction. The exclusion does not depend on frequency, how proceeds are used, or whether paid staff operate the games. The policy rationale excludes bingo only where the exempt organization does not compete with commercial bingo operations.', 'easy', 1),

-- Q17: easy / L1 — Schedule B contributor confidentiality
(3, 'Tax-Exempt Organizations', 'Which Form 990 schedule reports contributor information and is not available for public inspection?', '["Schedule B — Schedule of Contributors", "Schedule A — Public Charity Status and Public Support", "Schedule J — Compensation Information", "Schedule O — Supplemental Information"]'::jsonb, 0, 'Under IRC Section 6104, Schedule B (Schedule of Contributors) is filed with the IRS but is not available for public inspection, protecting donor privacy. All other Form 990 schedules, including Schedule A (public charity status), Schedule J (compensation), and Schedule O (supplemental information), are part of the publicly available return. This confidentiality provision prevents disclosure of the identities and contribution amounts of individual donors.', 'easy', 1),

-- Q18: easy / L1 — Donated goods exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Under Section 513(a)(3), which activity qualifies for the donated goods exclusion from UBIT?', '["A retail store selling new merchandise purchased at wholesale prices", "An auction of items handcrafted by paid artisans", "A bookstore selling textbooks purchased from publishers", "A thrift store selling clothing and household items donated to the organization"]'::jsonb, 3, 'Under IRC Section 513(a)(3), a trade or business is excluded from UBIT if substantially all merchandise sold has been received as gifts or contributions (donated goods). A thrift store selling donated clothing meets this criterion. Stores selling new or purchased merchandise, whether at wholesale prices, from publishers, or handcrafted by paid workers, do not qualify because the goods were not donated to the organization.', 'easy', 1),

-- Q19: medium / L2 — Form 990 late-filing penalties ($20/day)
(3, 'Tax-Exempt Organizations', 'Valley Arts Alliance, a 501(c)(3) with $600,000 in gross receipts, files its Form 990 seventy-five days late without reasonable cause. Under IRC Section 6652(c), what penalty applies?', '["$750 (computed at $10 per day)", "$7,500 (computed at $100 per day)", "$1,500 (computed at $20 per day for 75 days)", "$10,500 (the maximum penalty regardless of days late)"]'::jsonb, 2, 'Under IRC Section 6652(c)(1)(A), organizations with gross receipts under $1,186,000 face a penalty of $20 per day for each day the return is late, up to the lesser of $10,500 or 5% of gross receipts. For Valley Arts Alliance, the penalty is $20 times 75 days, equaling $1,500, which is below the $10,500 cap. The $100 per day rate applies only to organizations with gross receipts of $1,186,000 or more.', 'medium', 2),

-- Q20: medium / L3 — Section 509(a)(1) one-third support test application
(3, 'Tax-Exempt Organizations', 'Sunrise Health Initiative, a 501(c)(3), received total support of $900,000 over four years: $200,000 from government grants, $110,000 from public contributions, and $590,000 from investment income and fees from disqualified persons. Apply the one-third support test under Section 509(a)(1) to determine the organization''s classification.', '["Private foundation because investment income and fees from disqualified persons exceed public support", "Public charity because public support of $310,000 exceeds one-third of total support of $900,000", "Private foundation because the $110,000 in public contributions alone does not meet the one-third threshold", "Public charity only if the organization can demonstrate that program service fees relate to its exempt purpose"]'::jsonb, 1, 'Under IRC Section 509(a)(1), an organization qualifies as a public charity if it normally receives at least one-third of its total support from governmental units and the general public. Public support includes government grants ($200,000) and public contributions ($110,000), totaling $310,000, which is 34.4% of total support ($900,000) and exceeds the one-third threshold. The fact that non-public sources provide the majority does not disqualify the organization if the one-third test is met.', 'medium', 3),

-- Q21: hard / L4 — Section 4958 intermediate sanctions detailed tax analysis
(3, 'Tax-Exempt Organizations', 'Metro Community Center, a 501(c)(3), hires its board chair''s spouse as development director at $280,000 when comparable positions pay $120,000 to $150,000. The board approved the salary based solely on the chair''s recommendation without a compensation study, comparability data, or concurrent documentation. The IRS determines the excess benefit is $130,000. Evaluate the tax consequences under Section 4958.', '["The director owes 25% ($32,500) and any manager who knowingly approved owes 10% up to $20,000 per transaction", "The organization owes 25% of the excess benefit and the director must return $130,000 within 90 days", "The director owes a 10% excise tax and the board chair is automatically disqualified from future service", "No excise tax applies because the development director is not an officer or director of the organization"]'::jsonb, 0, 'Under IRC Section 4958, the director is a disqualified person as a family member of someone with substantial influence. The 25% initial tax on the $130,000 excess benefit equals $32,500, owed by the disqualified person. Organization managers who knowingly approved owe 10% up to $20,000 per transaction. The rebuttable presumption of reasonableness was not established because the board lacked independent approval, comparability data, and contemporaneous documentation. The organization itself is not taxed under intermediate sanctions.', 'hard', 4),

-- Q22: hard / L4 — Section 4943 excess business holdings combined ownership analysis
(3, 'Tax-Exempt Organizations', 'Parkview Foundation, a private foundation, owns 12% of GreenTech Corp. voting stock. The foundation''s substantial contributors collectively own 15%. An unrelated party offers to sell the foundation an additional 5% block. The investment manager believes the purchase is permissible because the foundation would hold only 17%, below the 20% threshold. Evaluate this analysis under Section 4943.', '["Correct, because the foundation''s 17% direct holdings do not exceed 20%", "Incorrect, because private foundations may not own voting stock in any for-profit corporation", "Incorrect, because combined holdings of the foundation and disqualified persons would total 32%, exceeding 20%", "Correct, because substantial contributors'' holdings are not attributed to the foundation"]'::jsonb, 2, 'Under IRC Section 4943, the excess business holdings rules limit the combined voting stock of a private foundation and all disqualified persons (including substantial contributors) to 20%. The investment manager considered only the foundation''s direct holdings (17%) without including the 15% owned by substantial contributors. Combined holdings of 32% would exceed the 20% permitted holding by 12%, triggering a 10% initial excise tax. Disqualified persons'' holdings must always be aggregated with the foundation''s.', 'hard', 4),

-- Q23: hard / L4 — Section 4945 private foundation lobbying as taxable expenditure
(3, 'Tax-Exempt Organizations', 'Crawford Medical Foundation, a private foundation, spends $85,000 producing research reports analyzing pending healthcare legislation and distributing them to members of Congress with explicit recommendations to support specific bills. The attorney argues this qualifies as protected educational activity. Evaluate whether this spending constitutes a taxable expenditure under Section 4945.', '["Not a taxable expenditure because producing research reports is an educational activity", "A taxable expenditure only if the foundation did not receive IRS pre-approval for lobbying", "A taxable expenditure because private foundations are prohibited from attempting to influence legislation under Section 4945(d)(1)", "A taxable expenditure only if the spending exceeds 5% of total annual expenditures"]'::jsonb, 2, 'Under IRC Section 4945(d)(1), any amount paid by a private foundation to influence legislation constitutes a taxable expenditure, subject to a 20% initial excise tax. Unlike public charities, private foundations have no de minimis lobbying allowance and cannot elect the Section 501(h) expenditure test. Distributing reports with explicit legislative recommendations to Congress is lobbying, not protected educational activity. The attorney''s characterization fails because the materials contain specific calls to action rather than neutral analysis.', 'hard', 4),

-- Q24: medium / L2 — Operational test: "primarily" standard vs. "exclusively"
(3, 'Tax-Exempt Organizations', 'Riverdale Youth Services, a 501(c)(3), allocates 70% of its budget to youth mentoring programs, 15% to administrative overhead, and 15% to operating a commercial printing business that generates revenue to fund its programs. Under the operational test, how does the IRS evaluate this allocation?', '["The organization fails because it must devote 100% of resources to exempt activities", "The organization likely passes because it is primarily engaged in activities accomplishing its exempt purpose", "The organization fails because commercial printing is never an exempt activity", "The organization automatically loses exempt status because 15% funds a commercial enterprise"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the operational test requires that an organization be operated primarily, not exclusively, for exempt purposes. An organization may engage in insubstantial non-exempt activities without failing the test. Devoting 70% to exempt activities plus 15% to necessary overhead demonstrates primary engagement in exempt purposes. The printing income may be subject to UBIT, but the presence of unrelated business activity does not by itself cause loss of exempt status.', 'medium', 2),

-- Q25: medium / L3 — Form 8868 six-month extension for Form 990
(3, 'Tax-Exempt Organizations', 'Pacific Arts Collective, a calendar-year 501(c)(3), realizes on May 1, 2026, that it cannot complete its Form 990 by the May 15 deadline due to a pending financial audit. The accountant files Form 8868 before the deadline. Under the filing extension rules, what is the new due date?', '["November 15, 2026, because Form 8868 provides an automatic six-month extension", "August 15, 2026, because Form 8868 provides only a three-month extension", "May 15, 2027, because the extension allows filing with the following year''s return", "September 15, 2026, because Form 8868 provides a four-month extension"]'::jsonb, 0, 'Under IRC Section 6081 and IRS Form 8868 instructions, tax-exempt organizations may obtain an automatic six-month extension to file Form 990 by submitting Form 8868 before the original due date. For a calendar-year organization with a May 15 deadline, the extended due date is November 15. The three-month extension was the former rule; the current single extension is for six months. The extension applies only to the filing deadline, not to any tax payment obligation.', 'medium', 3),

-- Q26: medium / L2 — Section 4941 foundation manager 5% tax on self-dealing
(3, 'Tax-Exempt Organizations', 'Golden Path Foundation, a private foundation, leases office space from its founder for $96,000 per year at fair market value. The chief financial officer, serving as a foundation manager, reviewed and approved the lease knowing the founder is a disqualified person. Under Section 4941, what excise tax is imposed on the foundation manager?', '["$9,600 (10% of the lease amount)", "$960 (1% of the lease amount)", "$19,200 (20% of the lease amount)", "$4,800 (5% of the lease amount for knowing participation)"]'::jsonb, 3, 'Under IRC Section 4941(a)(2), a foundation manager who knowingly participates in an act of self-dealing is subject to a 5% excise tax on the amount involved. The lease payment of $96,000 times 5% equals $4,800. The 10% initial tax under Section 4941(a)(1) applies to the self-dealer (the founder), not the manager. Self-dealing is based on the nature of the transaction — any lease between a foundation and a disqualified person is prohibited regardless of fair market value.', 'medium', 2),

-- Q27: medium / L3 — Section 509(a)(2) gross receipts test for public charity
(3, 'Tax-Exempt Organizations', 'Maple Street Clinic, a 501(c)(3), receives $400,000 in patient fees related to its exempt purpose, $80,000 in public donations, and $120,000 in investment income over four years. Under the Section 509(a)(2) gross receipts test, does the clinic qualify as a public charity?', '["No, because patient fees exceed contributions and cannot count toward the support test", "Yes, because more than one-third of support comes from contributions and exempt-function gross receipts, and investment income does not exceed one-third", "No, because investment income of $120,000 disqualifies the organization from public charity status", "Yes, but only if the clinic can demonstrate that all patients are low-income"]'::jsonb, 1, 'Under IRC Section 509(a)(2), an organization qualifies as a public charity if it receives more than one-third of support from contributions, membership fees, and gross receipts from exempt-function activities. The clinic''s qualifying support is $480,000 ($400,000 fees plus $80,000 donations), which is 80% of total support — well above one-third. Investment income of $120,000 is only 20%, below the one-third cap. Patient fees from activities related to the exempt purpose count as favorable support under 509(a)(2).', 'medium', 3),

-- Q28: medium / L2 — UBIT taxed at corporate rate for exempt corporations
(3, 'Tax-Exempt Organizations', 'Greenfield Community Foundation, a 501(c)(3) organized as a nonprofit corporation, has $200,000 of net unrelated business taxable income for 2026 after the $1,000 specific deduction. At what rate is this income taxed?', '["A flat 15% rate applicable to nonprofit corporations", "The graduated individual income tax rates", "The 21% flat corporate tax rate under Section 11", "No tax applies because the income supports the organization''s exempt mission"]'::jsonb, 2, 'Under IRC Section 511(a), unrelated business taxable income of a 501(c)(3) organization structured as a corporation is taxed at the regular corporate rate of 21% under Section 11. The fact that UBI funds exempt activities does not exempt it from taxation. Organizations structured as trusts are instead taxed at trust rates under Section 1(e). The policy behind UBIT prevents tax-exempt organizations from gaining an unfair competitive advantage over taxable businesses.', 'medium', 2),

-- Q29: medium / L2 — Private benefit: incidental vs. impermissible
(3, 'Tax-Exempt Organizations', 'Horizon Arts Academy, a 501(c)(3) music school, hires a renowned musician as lead instructor at a fair market salary. The musician gains significant professional visibility and reputation enhancement from the appointment. How should this benefit be characterized under the private benefit doctrine?', '["The benefit is incidental and qualitative, arising naturally from the organization''s exempt purpose, and does not violate the doctrine", "The benefit is impermissible because any reputational gain by an individual constitutes private benefit", "The benefit is permissible only if the musician is a volunteer rather than a paid employee", "The benefit violates the doctrine because the musician is not a disqualified person"]'::jsonb, 0, 'Under IRC Section 501(c)(3), the private benefit doctrine prohibits benefits to private individuals that are more than incidental in both qualitative and quantitative terms. When an instructor receives fair compensation and reputational benefit arises incidentally from furthering the organization''s educational mission, the benefit is considered incidental. Private benefit analysis focuses on whether the benefit is a necessary by-product of exempt activities, not whether any benefit whatsoever exists.', 'medium', 2),

-- Q30: hard / L3 — UBIT "regularly carried on" test: seasonal activity analysis
(3, 'Tax-Exempt Organizations', 'Lakeshore Community Alliance, a 501(c)(3), operates a holiday gift wrap booth at a shopping mall for four weeks between Thanksgiving and Christmas each year. The booth generates $35,000 in revenue, is staffed by paid workers, and is unrelated to the organization''s educational mission. Apply the three-part UBIT test, focusing on whether this activity is regularly carried on.', '["Subject to UBIT because the activity satisfies all three parts of the test", "Subject to UBIT because any commercial activity generating over $1,000 is automatically regularly carried on", "Not subject to UBIT because the activity is staffed by paid employees rather than volunteers", "Not subject to UBIT because a four-week seasonal activity is not carried on with frequency and continuity comparable to commercial enterprises"]'::jsonb, 3, 'Under IRC Section 512 and Treasury Regulations Section 1.513-1(c)(2)(i), the regularly-carried-on test compares the duration and recurrence of the exempt organization''s activity to commercial counterparts. While the gift wrap booth is a trade or business unrelated to the educational mission, a four-week seasonal activity lacks the frequency and continuity of year-round commercial gift-wrapping services. Short seasonal activities are generally not regularly carried on, so the second prong of the three-part test is not met.', 'hard', 3)
;

COMMIT;
